// Package rt is the runtime core that code generated by the Alder compiler
// imports: the containers behind Maybe, Result, Dict and Date, and the
// small helpers the emitter uses for operators and string interpolation.
package rt

import (
	"fmt"
	"net/url"
	"reflect"
	"slices"
	"strconv"
	"strings"
	"time"
)

// Maybe is Alder's `Maybe a`. The zero value is Nothing.
type Maybe[T any] struct {
	Ok  bool
	Val T
}

// Just wraps a value.
func Just[T any](v T) Maybe[T] { return Maybe[T]{Ok: true, Val: v} }

// Nothing is the empty Maybe.
func Nothing[T any]() Maybe[T] { return Maybe[T]{} }

// Result is Alder's `Result e a`.
type Result[E, T any] struct {
	IsOk bool
	Val  T
	Err  E
}

// Ok is a successful Result.
func Ok[E, T any](v T) Result[E, T] { return Result[E, T]{IsOk: true, Val: v} }

// Err is a failed Result.
func Err[E, T any](e E) Result[E, T] { return Result[E, T]{Err: e} }

// Dict is Alder's `Dict k v`: an immutable map that remembers the order in
// which keys were first inserted. The zero value is the empty Dict.
// Insert and Remove return a new Dict and never change the receiver.
//
// A key may be of any Alder type (a List, a record, a Time, …), so the map
// is keyed by the key's canonical encoding, Key(k): two keys are the same
// key exactly when their encodings are equal, which is when they are Eq.
type Dict[K, V any] struct {
	m    map[string]V
	keys []K
	encs []string // Key of each of keys
}

// Get looks a key up.
func (d Dict[K, V]) Get(k K) (V, bool) {
	v, ok := d.m[Key(k)]
	return v, ok
}

// Has reports whether the key is present.
func (d Dict[K, V]) Has(k K) bool {
	_, ok := d.m[Key(k)]
	return ok
}

// Len is the number of entries.
func (d Dict[K, V]) Len() int { return len(d.keys) }

// Keys returns the keys in insertion order, as a fresh slice.
func (d Dict[K, V]) Keys() []K { return append([]K{}, d.keys...) }

// Values returns the values in key insertion order.
func (d Dict[K, V]) Values() []V {
	vs := make([]V, len(d.keys))
	for i, e := range d.encs {
		vs[i] = d.m[e]
	}
	return vs
}

// Insert returns a Dict with k bound to v. A key already present keeps its
// position (and its first spelling, e.g. the first Time zone); a new key
// goes last.
func (d Dict[K, V]) Insert(k K, v V) Dict[K, V] {
	c := d.clone()
	c.Put(k, v)
	return c
}

// Remove returns a Dict without k.
func (d Dict[K, V]) Remove(k K) Dict[K, V] {
	enc := Key(k)
	if _, ok := d.m[enc]; !ok {
		return d
	}
	c := Dict[K, V]{m: make(map[string]V, len(d.m)), keys: make([]K, 0, len(d.keys)), encs: make([]string, 0, len(d.encs))}
	for i, e := range d.encs {
		if e != enc {
			c.keys = append(c.keys, d.keys[i])
			c.encs = append(c.encs, e)
			c.m[e] = d.m[e]
		}
	}
	return c
}

// Put binds k to v in place. It is for building a Dict that no Alder code
// has seen yet (e.g. inside a stdlib function); everything else uses Insert.
func (d *Dict[K, V]) Put(k K, v V) {
	if d.m == nil {
		d.m = map[string]V{}
	}
	enc := Key(k)
	if _, ok := d.m[enc]; !ok {
		d.keys = append(d.keys, k)
		d.encs = append(d.encs, enc)
	}
	d.m[enc] = v
}

// Equal reports whether both dicts hold the same keys with Eq values.
// Insertion order is ignored.
func (d Dict[K, V]) Equal(o Dict[K, V]) bool {
	if len(d.m) != len(o.m) {
		return false
	}
	for e, v := range d.m {
		ov, ok := o.m[e]
		if !ok || !Eq(v, ov) {
			return false
		}
	}
	return true
}

func (d Dict[K, V]) eqAny(o any) bool { return d.Equal(o.(Dict[K, V])) }

// keyAny is the Dict's own canonical encoding, for a Dict used inside a key:
// its entries sorted by key encoding, so that insertion order is ignored as
// Equal ignores it.
func (d Dict[K, V]) keyAny(b *strings.Builder) {
	encs := slices.Clone(d.encs)
	slices.Sort(encs)
	b.WriteString("d")
	for _, e := range encs {
		writeLen(b, e)
		keyValue(b, reflect.ValueOf(d.m[e]))
	}
	b.WriteString(")")
}

func (d Dict[K, V]) clone() Dict[K, V] {
	c := Dict[K, V]{
		m:    make(map[string]V, len(d.m)+1),
		keys: make([]K, len(d.keys), len(d.keys)+1),
		encs: make([]string, len(d.encs), len(d.encs)+1),
	}
	copy(c.keys, d.keys)
	copy(c.encs, d.encs)
	for k, v := range d.m {
		c.m[k] = v
	}
	return c
}

// Key is the canonical encoding of a Dict key: Key(a) == Key(b) exactly when
// Eq(a, b) (except that NaN, which is not Eq to itself, is one key). Text,
// Int, Float and Bool are encoded directly (Float -0 as 0); a Time as its
// UTC instant (UnixNano), so the same instant in two locations is one key;
// a Dict as its entries in key order; records, unions, Maybe, Result and
// Date field by field; lists element by element, with nil and empty the
// same. Every variable-length part is length-prefixed, so no two values
// share an encoding. A function cannot be a key: Key panics. The '_' field
// limitation of Eq applies: a Time in such a field is keyed by its
// representation, and a Dict there makes Key panic.
func Key(k any) string {
	var b strings.Builder
	keyValue(&b, reflect.ValueOf(k))
	return b.String()
}

// dictKey is implemented by every Dict instantiation.
type dictKey interface{ keyAny(b *strings.Builder) }

func writeLen(b *strings.Builder, s string) {
	b.WriteString(strconv.Itoa(len(s)))
	b.WriteByte(':')
	b.WriteString(s)
}

func keyValue(b *strings.Builder, v reflect.Value) {
	if !v.IsValid() {
		b.WriteString("0")
		return
	}
	if v.Type() == timeType && v.CanInterface() {
		b.WriteString("t")
		b.WriteString(strconv.FormatInt(v.Interface().(time.Time).UnixNano(), 10))
		b.WriteByte(';')
		return
	}
	if v.Kind() == reflect.Struct && v.CanInterface() {
		if d, ok := v.Interface().(dictKey); ok {
			d.keyAny(b)
			return
		}
	}
	switch v.Kind() {
	case reflect.String:
		b.WriteString("s")
		writeLen(b, v.String())
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		b.WriteString("i")
		b.WriteString(strconv.FormatInt(v.Int(), 10))
		b.WriteByte(';')
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
		b.WriteString("u")
		b.WriteString(strconv.FormatUint(v.Uint(), 10))
		b.WriteByte(';')
	case reflect.Float32, reflect.Float64:
		f := v.Float()
		if f == 0 {
			f = 0 // -0 is 0
		}
		b.WriteString("f")
		b.WriteString(strconv.FormatFloat(f, 'g', -1, 64))
		b.WriteByte(';')
	case reflect.Bool:
		if v.Bool() {
			b.WriteString("T")
		} else {
			b.WriteString("F")
		}
	case reflect.Struct:
		b.WriteString("{")
		for i := range v.NumField() {
			keyValue(b, v.Field(i))
		}
		b.WriteString("}")
	case reflect.Slice, reflect.Array:
		b.WriteString("[")
		b.WriteString(strconv.Itoa(v.Len()))
		b.WriteByte(':')
		for i := range v.Len() {
			keyValue(b, v.Index(i))
		}
		b.WriteString("]")
	case reflect.Pointer:
		if v.IsNil() {
			b.WriteString("n")
			return
		}
		b.WriteString("p")
		keyValue(b, v.Elem())
	case reflect.Interface:
		if v.IsNil() {
			b.WriteString("n")
			return
		}
		b.WriteString("a")
		writeLen(b, v.Elem().Type().String())
		keyValue(b, v.Elem())
	default:
		panic("alder: a value of type " + v.Type().String() + " cannot be a Dict key")
	}
}

// Eq is Alder's one structural equality. The emitter uses it for `==` and
// `!=` on every non-primitive type, and rt/std uses it wherever it compares
// values. Time is compared as an instant (Time.Equal); a Dict by its key set
// and Eq on each value, ignoring insertion order; structs (records, unions,
// Maybe, Result, Date) field by field; slices element-wise, with nil and
// empty equal; union payloads through their pointers; everything else by
// ==. So a Float follows IEEE: NaN is not Eq to itself, and -0 is Eq to 0.
//
// Limitation: a record field whose Alder name starts with '_' is an
// unexported Go field (`_at`), and reflect cannot hand Eq its value as an
// interface. A Time or Dict held there is compared field by field instead:
// the same instant in two locations, or the same entries inserted in
// another order, compare unequal. (Key panics on a Dict there.)
func Eq[T any](a, b T) bool {
	switch x := any(a).(type) {
	case string:
		return x == any(b).(string)
	case int64:
		return x == any(b).(int64)
	case float64:
		return x == any(b).(float64)
	case bool:
		return x == any(b).(bool)
	}
	return eqValue(reflect.ValueOf(&a).Elem(), reflect.ValueOf(&b).Elem())
}

// dictEq is implemented by every Dict instantiation.
type dictEq interface{ eqAny(o any) bool }

var timeType = reflect.TypeFor[time.Time]()

func eqValue(a, b reflect.Value) bool {
	if a.Type() != b.Type() {
		return false
	}
	if a.Type() == timeType && a.CanInterface() {
		return a.Interface().(time.Time).Equal(b.Interface().(time.Time))
	}
	if a.CanInterface() {
		if d, ok := a.Interface().(dictEq); ok && a.Kind() == reflect.Struct {
			return d.eqAny(b.Interface())
		}
	}
	switch a.Kind() {
	case reflect.Struct:
		for i := range a.NumField() {
			if !eqValue(a.Field(i), b.Field(i)) {
				return false
			}
		}
		return true
	case reflect.Slice, reflect.Array:
		if a.Len() != b.Len() {
			return false
		}
		for i := range a.Len() {
			if !eqValue(a.Index(i), b.Index(i)) {
				return false
			}
		}
		return true
	case reflect.Map:
		if a.Len() != b.Len() {
			return false
		}
		for it := a.MapRange(); it.Next(); {
			bv := b.MapIndex(it.Key())
			if !bv.IsValid() || !eqValue(it.Value(), bv) {
				return false
			}
		}
		return true
	case reflect.Pointer, reflect.Interface:
		if a.IsNil() || b.IsNil() {
			return a.IsNil() && b.IsNil()
		}
		if a.Kind() == reflect.Pointer && a.Pointer() == b.Pointer() {
			return true
		}
		return eqValue(a.Elem(), b.Elem())
	case reflect.Func:
		return false // functions have no equality
	default:
		return a.Equal(b)
	}
}

// Date is Alder's calendar `Date` (no time zone).
type Date struct{ Y, M, D int }

// Time converts the date to midnight UTC.
func (d Date) Time() time.Time {
	return time.Date(d.Y, time.Month(d.M), d.D, 0, 0, 0, 0, time.UTC)
}

// DateOf is the UTC calendar date of an instant.
func DateOf(t time.Time) Date {
	y, m, d := t.UTC().Date()
	return Date{Y: y, M: int(m), D: d}
}

// Format renders a date with a Go layout string, e.g. "Jan 2, 2006".
func Format(layout string, d Date) string { return d.Time().Format(layout) }

// HttpError is the stdlib `Http.HttpError`: why an Http.get or Http.post did not produce a 2xx
// response. Status is the response's status code, or 0 when there was no response (a transport
// failure or timeout); Message is the response body, or the error.
type HttpError struct {
	Status  int64
	Message string
}

// Page is a link target. M3c fills it in; M3a needs only the type.
type Page struct {
	Path string
}

// PageURL is the URL a link to p points at: `href={…}` renders it. In M3a it is p's path (with
// path parameters already filled in by the generated code); M3c adds the query parameters.
func PageURL(p Page) string { return p.Path }

// KV is one message parameter: its name and its value as text.
type KV struct{ Key, Value string }

// MsgURL is the URL a message is posted to: /_m/<module>/<msg>, then the message's parameters
// (in declaration order) as an URL-encoded query string. `click` and `submit` attributes post to
// it; M3c routes it to the page's update.
func MsgURL(module, msg string, params ...KV) string {
	u := "/_m/" + module + "/" + msg
	for i, p := range params {
		sep := "&"
		if i == 0 {
			sep = "?"
		}
		u += sep + url.QueryEscape(p.Key) + "=" + url.QueryEscape(p.Value)
	}
	return u
}

// MaybeText is a Maybe's value as text, "" for Nothing. The generated code uses it for message
// parameters and form values of a Maybe type.
func MaybeText[T any](m Maybe[T], text func(T) string) string {
	if !m.Ok {
		return ""
	}
	return text(m.Val)
}

// TextOf is any other value as text (fmt's %v), for message parameters of a type with no text
// form of its own (records, lists, unions with payloads).
func TextOf(v any) string { return fmt.Sprint(v) }

// Concat joins the pieces of an interpolated string.
func Concat(parts ...string) string { return strings.Join(parts, "") }

// OrElse is the `??` operator.
func OrElse[T any](m Maybe[T], d T) T {
	if m.Ok {
		return m.Val
	}
	return d
}

// Append is `++` on lists. The result never shares storage with a or b.
func Append[T any](a, b []T) []T {
	out := make([]T, 0, len(a)+len(b))
	out = append(out, a...)
	return append(out, b...)
}

// Unit is Alder's `Unit` value.
func Unit() struct{} { return struct{}{} }

// DateCmp orders dates: negative when a is before b, 0 when equal, positive when after. The
// emitter uses it for `<`, `<=`, `>`, `>=` on Date.
func DateCmp(a, b Date) int {
	switch {
	case a.Y != b.Y:
		return a.Y - b.Y
	case a.M != b.M:
		return a.M - b.M
	}
	return a.D - b.D
}

// TimeCmp orders instants like DateCmp: the emitter uses it for ordered comparisons on Time.
func TimeCmp(a, b time.Time) int { return a.Compare(b) }

// Int is the identity on Int. The emitter routes a literal through it where Go would otherwise
// evaluate an operator at compile time (`9223372036854775807 + 1`, `1 / 0`): Alder's Int
// arithmetic wraps on overflow and fails at run time on division by zero, and Go only does that
// for values, not constants.
func Int(n int64) int64 { return n }

// Float is the identity on Float, for the same purpose as Int (`1.0 / 0.0` is +Inf at run time).
func Float(f float64) float64 { return f }
